        _0 = _1 + _2;
        return;
    }
}

fn add_two(_1: i32) -> i32 {
    let mut _0: i32;

    BB0 {
        _0 = call add(_1, 2);
    }

    // Need a new basic block because of the call in BB0.
    BB1 {
        return;
    }
}
